package com.dukankhata.closing;
import com.dukankhata.shop.Shop; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Entity @Table(name="daily_closings",uniqueConstraints=@UniqueConstraint(name="uk_closing_shop_date",columnNames={"shop_id","closing_date"}),indexes=@Index(name="idx_closing_shop_date",columnList="shop_id,closing_date")) public class DailyClosing { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="shop_id",nullable=false) private Shop shop; @Column(name="closing_date",nullable=false) private LocalDate businessDate; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ClosingStatus status=ClosingStatus.OPEN; @Column(nullable=false,precision=14,scale=2) private BigDecimal expectedSales=BigDecimal.ZERO; @Column(nullable=false,precision=14,scale=2) private BigDecimal cash=BigDecimal.ZERO; @Column(nullable=false,precision=14,scale=2) private BigDecimal upi=BigDecimal.ZERO; @Column(nullable=false,precision=14,scale=2) private BigDecimal udhar=BigDecimal.ZERO; @Column(nullable=false,precision=14,scale=2) private BigDecimal actualCollection=BigDecimal.ZERO; @Column(nullable=false,precision=14,scale=2) private BigDecimal variance=BigDecimal.ZERO; @Column(nullable=false,precision=14,scale=2) private BigDecimal expensesTotal=BigDecimal.ZERO; @Column(nullable=false,precision=14,scale=2) private BigDecimal netProfit=BigDecimal.ZERO; @Column(nullable=false) private Boolean posAutoAggregated=false; @Column(nullable=false) private Long posSaleCount=0L; @Column(nullable=false,precision=14,scale=2) private BigDecimal posSalesTotal=BigDecimal.ZERO; @Column(length=500) private String notes; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; private Instant closedAt; @OneToMany(mappedBy="closing",cascade=CascadeType.ALL,orphanRemoval=true) private List<DailyClosingItem> items=new ArrayList<>(); @OneToMany(mappedBy="closing",cascade=CascadeType.ALL,orphanRemoval=true) private List<ClosingExpense> expenses=new ArrayList<>(); @PrePersist void onCreate(){Instant now=Instant.now();createdAt=now;updatedAt=now;} @PreUpdate void onUpdate(){updatedAt=Instant.now();}
public UUID getId(){return id;} public Shop getShop(){return shop;} public LocalDate getBusinessDate(){return businessDate;} public ClosingStatus getStatus(){return status;} public BigDecimal getExpectedSales(){return expectedSales;} public BigDecimal getCash(){return cash;} public BigDecimal getUpi(){return upi;} public BigDecimal getUdhar(){return udhar;} public BigDecimal getActualCollection(){return actualCollection;} public BigDecimal getVariance(){return variance;} public BigDecimal getExpensesTotal(){return expensesTotal;} public BigDecimal getNetProfit(){return netProfit;} public Boolean getPosAutoAggregated(){return posAutoAggregated;} public Long getPosSaleCount(){return posSaleCount;} public BigDecimal getPosSalesTotal(){return posSalesTotal;} public String getNotes(){return notes;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public Instant getClosedAt(){return closedAt;} public List<DailyClosingItem> getItems(){return items;} public List<ClosingExpense> getExpenses(){return expenses;} public void setShop(Shop v){shop=v;} public void setBusinessDate(LocalDate v){businessDate=v;} public void setStatus(ClosingStatus v){status=v;} public void setExpectedSales(BigDecimal v){expectedSales=v;} public void setCash(BigDecimal v){cash=v;} public void setUpi(BigDecimal v){upi=v;} public void setUdhar(BigDecimal v){udhar=v;} public void setActualCollection(BigDecimal v){actualCollection=v;} public void setVariance(BigDecimal v){variance=v;} public void setExpensesTotal(BigDecimal v){expensesTotal=v;} public void setNetProfit(BigDecimal v){netProfit=v;} public void setPosAutoAggregated(Boolean v){posAutoAggregated=v;} public void setPosSaleCount(Long v){posSaleCount=v;} public void setPosSalesTotal(BigDecimal v){posSalesTotal=v;} public void setNotes(String v){notes=v;} public void setClosedAt(Instant v){closedAt=v;} }
